export const getMikrotikV2Icon = (
  iconId: string | undefined | null
): Icon | null => {
  if (!iconId) return null;
  return (
    MIKROTIK_V2_ICONS.find((icon) => {
      return icon.id === iconId;
    }) ?? null
  );
};

export const ensureMikrotikV2Icons = (icons: Icon[]): Icon[] => {
  const byId = new Map(
    icons.map((icon) => {
      return [icon.id, icon] as const;
    })
  );
  MIKROTIK_V2_ICONS.forEach((icon) => {
    byId.set(icon.id, icon);
  });
  return Array.from(byId.values());
};
